// SLUGBERT — a spotted garden slug with a stretchy snout and far more slime than is reasonable.
//   STRIKE   (attack button)   SNOUT SLAP: the snout shoots out like a rubber tongue.
//   GIMMICK  (special button)  SLIME: spit a glob; sideways it slides on a goo trail; down it lays a sticky puddle.
//                              Every gimmick spends SLIME, which slowly oozes back. Crawling leaves a trail:
//                              Slugbert glides at double speed on his own slime, everyone else slips on it.
//   RECOVERY (up + special)    GOO GEYSER: sneezes a jet of slime at the ground and rides it up.
export default function make(api) {
  const { hb, cap, key, mv, spawnProjectile, spriteAnims, spriteLoops, B } = api;

  const stats = {
    weight: 100, walk: 2.8, run: 5.2, dashInit: 6, airSpeed: 3.9, airAccel: 0.16,
    fallSpeed: 6, fastFall: 9.5, gravity: 0.4, shortHop: 7.5, fullHop: 12, doubleJump: 11.5,
    jumps: 2, wallJump: false, traction: 0.62, height: 120, width: 110, crouchHeight: 70, landLag: 5, ledgeReach: 40,
  };

  const P = (extra) => ({ ...extra });
  const rest = P({});
  // a slug squashes more than it leans
  const strikePoses = (total, hit, lean, extra = {}) => [
    key(0, P({ rot: -lean * 0.4, sx: 0.9, sy: 1.1, ...extra })),
    key(hit, P({ rot: lean, sx: 1.18, sy: 0.88, ...extra })),
    key(Math.min(total - 1, hit + 6), P({ rot: lean * 0.7, sx: 1.06, sy: 0.96, ...extra })),
    key(total, rest),
  ];
  const SNOUT = { fx: "snout" };
  // draws (at the bottom) draw every move; a look only names a hitbox's `fx` and colours its hit sparks
  const looks = {
    snout: { color: "#9ddca8" }, splat: { color: "#b6f0bf" }, glob: { color: "#8fd49b" },
    puddle: { color: "#8fd49b" }, slime: { color: "#5fc94a" }, geyser: { color: "#a8e0b0" },
  };

  // THE STRIKE: the snout stretches from the face (about 57 units up) out to 82 units, 11 damage.
  const STRIKE = { total: 28, hit: 7, active: 5, damage: 12, r: 20 };
  const aim = (id, dir, opts = {}) => {
    const s = { ...STRIKE, ...opts };
    const end = dir === "u" ? [36, -140] : dir === "b" ? [-100, -57] : dir === "d" ? [92, -20] : [104, -57];
    const start = dir === "u" ? [8, -90] : dir === "b" ? [-20, -57] : dir === "d" ? [10, -22] : [20, -57];
    const angle = dir === "u" ? 86 : dir === "d" ? 30 : 40;
    const lean = dir === "u" ? -4 : dir === "b" ? -14 : dir === "d" ? 4 : 10;
    const extra = dir === "d" ? { sy: 0.9, dy: 4 } : dir === "u" ? { sy: 1.14, sx: 0.9 } : {};
    const cell = dir === "u" ? "atk-up" : dir === "d" ? "atk-down" : "atk-fwd";
    return mv(id, s.total, [cap([s.hit, s.hit + s.active - 1], start[0], start[1], end[0], end[1], s.r, s.damage, angle, s.base ?? 44, s.growth ?? 88, { ...SNOUT, ...(s.hb ?? {}) })],
      strikePoses(s.total, s.hit, lean, extra), { cell, cellFlip: dir === "b", ...(s.mv ?? {}) });
  };

  const SLIME_MAX = 100;

  const moves = {
    jab1: aim("jab1", "f", { total: 22, hit: 6, damage: 6, mv: { iasa: 17 } }),
    ftilt: aim("ftilt", "f"),
    dashAttack: aim("dashAttack", "f", { total: 38, hit: 9, damage: 11, mv: { motion: [[1, 6, 0], [12, 3, 0], [20, 1, 0]], cell: "atk-down" } }),
    nair: aim("nair", "f", { total: 30, hit: 7, damage: 9, mv: { aerial: true, landingLag: 10 } }),
    fair: aim("fair", "f", { mv: { aerial: true, landingLag: 12 } }),
    bair: aim("bair", "b", { damage: 13, mv: { aerial: true, landingLag: 12 } }),
    utilt: aim("utilt", "u", { damage: 10 }),
    uair: aim("uair", "u", { damage: 10, mv: { aerial: true, landingLag: 10 } }),
    dtilt: aim("dtilt", "d", { damage: 9 }),
    // belly flop: the whole slug slams down, spiking anyone under it
    dair: mv("dair", 42, [cap([14, 20], -40, -10, 40, -10, 22, 13, 270, 30, 70, { ...SNOUT, spike: true })],
      [key(0, P({ sy: 1.1, sx: 0.9 })), key(14, P({ sy: 0.78, sx: 1.22 })), key(24, P({ sy: 0.86, sx: 1.12 })), key(42, rest)],
      { aerial: true, landingLag: 16, cell: "atk-down" }),
    // the charged slap: the snout snaps out further, with a sweet spot at its tip
    fsmash: mv("fsmash", 52, [
      cap([16, 19], 70, -57, 118, -57, 18, 19, 38, 46, 100, { fx: "splat", priority: 0 }),
      cap([16, 21], 20, -57, 80, -57, 22, 14, 40, 40, 82, { ...SNOUT, priority: 1 }),
    ], strikePoses(52, 16, 14, { dx: 8 }), { smash: true }),
    usmash: aim("usmash", "u", { total: 50, hit: 15, active: 6, damage: 17, base: 42, growth: 98, mv: { smash: true } }),
    dsmash: mv("dsmash", 54, [
      cap([16, 19], 10, -24, 100, -22, 22, 15, 30, 45, 88, { ...SNOUT, group: 0 }),
      cap([22, 25], -10, -24, -100, -22, 22, 15, 30, 45, 88, { ...SNOUT, group: 1 }),
    ], [key(0, P({ sy: 1.06 })), key(16, P({ sx: 1.25, sy: 0.78 })), key(22, P({ sx: 1.25, sy: 0.78, dx: -10 })), key(54, rest)], { smash: true, cell: "atk-down" }),
    // GIMMICK: spit a glob of slime in an arc
    nspecial: mv("nspecial", 40, [], [key(0, P({ sy: 1.12, sx: 0.9 })), key(12, P({ sy: 1.16, sx: 0.88, rot: -6 })), key(14, P({ sy: 0.86, sx: 1.16, rot: 8 })), key(26, P({ sy: 0.96 })), key(40, rest)], { hook: "spit" }),
    // sideways: slide forward on a slime trail, body first, leaving a puddle where it started
    sspecial: mv("sspecial", 44, [cap([8, 22], -20, -40, 50, -30, 30, 10, 38, 45, 70, { ...SNOUT })],
      [key(0, P({ sy: 1.1, sx: 0.88 })), key(8, P({ sy: 0.78, sx: 1.3 })), key(22, P({ sy: 0.8, sx: 1.26 })), key(44, rest)],
      { hook: "slide", cell: "atk-down" }),
    // down: lay a sticky puddle at your feet that pops the next person who steps in it
    dspecial: mv("dspecial", 36, [], [key(0, rest), key(10, P({ sy: 0.72, sx: 1.25 })), key(20, P({ sy: 0.74, sx: 1.22 })), key(36, rest)], { hook: "puddle", cell: "block" }),
    // RECOVERY: GOO GEYSER, a jet of slime blasts at the ground and carries it up, steerable
    uspecial: mv("uspecial", 56, [hb([4, 12], 0, 10, 40, 8, 80, 50, 55, { fx: "geyser" })],
      [key(0, P({ sy: 0.72, sx: 1.2 })), key(4, P({ sy: 1.24, sx: 0.84 })), key(30, P({ sy: 1.1, sx: 0.94, rot: 4 })), key(56, P({ rot: -8 }))],
      { hook: "geyser", helpless: true, ledgeOk: true, cell: "jump" }),
    ledgeAttack: aim("ledgeAttack", "f", { total: 40, hit: 12, damage: 9 }),
    getupAttack: mv("getupAttack", 44, [cap([12, 15], 10, -14, 90, -12, 20, 7, 45, 40, 60, { ...SNOUT, group: 0 }), cap([20, 23], -10, -14, -90, -12, 20, 7, 45, 40, 60, { ...SNOUT, group: 1 })], [key(0, rest), key(12, P({ sx: 1.2, sy: 0.82 })), key(20, P({ sx: 1.2, sy: 0.82 })), key(44, rest)], { cell: "atk-down" }),
    taunt: mv("taunt", 56, [], [key(0, rest), key(10, P({ sy: 1.18, sx: 0.88 })), key(20, P({ sy: 0.8, sx: 1.2 })), key(30, P({ sy: 1.18, sx: 0.88 })), key(40, P({ sy: 0.8, sx: 1.2 })), key(56, rest)], { cell: "atk-up" }),
  };

  // spend slime; a dry slug just goes through the motion
  const spend = (f, cost) => {
    if (f.bars.slime < cost) return false;
    f.bars.slime -= cost;
    return true;
  };
  // THE TRAIL: a ring of N slime patches on the special state; each slot is x, y (floor height), w (half-width), t (frames left).
  // The drawn patch is a projectile that never hits (its hitbox is active on no frame).
  const N = 16;
  const stamp = (state, f, x, y, w, life) => {
    const s = f.special;
    const i = s.next;
    s["x" + i] = x; s["y" + i] = y; s["w" + i] = w; s["t" + i] = life;
    s.next = (i + 1) % N;
    spawnProjectile(state, f, "slime", x, y - 2, 0, 0, life,
      { frames: [100000, 100000], x: 0, y: 0, r: Math.min(w, 30), damage: 0, angle: 0, base: 0, growth: 0 }, { g: 0 });
  };
  const onSlime = (s, x, y) => {
    for (let i = 0; i < N; i++) {
      if (s["t" + i] > 0 && Math.abs(y - s["y" + i]) < 6 && Math.abs(x - s["x" + i]) <= s["w" + i]) return true;
    }
    return false;
  };
  const layPuddle = (state, f, x, life, damage) =>
    spawnProjectile(state, f, "puddle", x, f.y - 6, 0, 0, life,
      { frames: [0, 999], x: 0, y: 0, r: 30, damage, angle: 88, base: 62, growth: 30 });

  // HOW HE IS DRAWN. The snout is a white rubber tube with his green outline that stretches out along the hitbox,
  // bulbs at the tip, and snaps back; everything else is slime: see-through green goo, drops that arc and fall.
  const MARK = "#4f9e63", GOO = { color: "#a6e3b0", ink: "#2f7a45" }, SKIN = "#fbfdf8";
  const drops = (g, c, s0, o = {}) => {
    const t = g.span(s0, s0 + (o.frames ?? 16)), n = o.n ?? 5, spread = o.spread ?? 90, dist = o.dist ?? 50;
    if (t <= 0 || t >= 1) return;
    for (let k = 0; k < n; k++) {
      const deg = (o.deg ?? 90) + (n === 1 ? 0 : (k / (n - 1) - 0.5) * spread) + (g.noise(s0 * 7 + k * 31) - 0.5) * 20;
      const p = g.toward(c, deg, dist * g.ease(t) * (0.6 + g.noise(k * 17 + s0) * 0.5));
      g.blob([p[0], p[1] + 34 * t * t], (o.r ?? 5) * (1 - t * 0.4), { ...GOO, alpha: 1 - t * t, seed: k * 13 + s0 });
    }
  };
  // the snout along hitbox i: shoots out with a whip in it, full length (past the hitbox's far edge) as it comes out,
  // holds, snaps back. o.w: thickness; o.heavy: a smash, with the spots and a hatched bulb; o.tipOf: reach to that hitbox's far end.
  const snout = (g, i, o = {}) => {
    const { near, h } = g.ends(i), far = g.ends(o.tipOf ?? i).far, [s0, e] = h.frames, lead = o.lead ?? 3, lag = o.lag ?? 7;
    if (g.frame < s0 - lead) return;
    const back = g.span(e, e + lag);
    if (back >= 1) return;
    const out = g.ease(g.span(s0 - lead, s0)), len = g.dist(near, far) || 1;
    const d = [(far[0] - near[0]) / len, (far[1] - near[1]) / len], nrm = [-d[1], d[0]];
    const tip = [far[0] + d[0] * h.r * 0.7, far[1] + d[1] * h.r * 0.7];
    const head = g.lerp(near, tip, out * (1 - back * 0.7));
    const bow = (o.bow ?? 1) * h.r * 0.9 * ((1 - out) + back * 0.6);
    const pts = [];
    for (let k = 0; k <= 32; k++) {
      const t = k / 32, p = g.lerp(near, head, t), b = bow * 4 * t * (1 - t);
      pts.push([p[0] + nrm[0] * b, p[1] + nrm[1] * b]);
    }
    // a round bulb at the end: the cap is as long as the bulb is wide
    const w = o.w ?? h.r * 1.1, alpha = 1 - back, cap = Math.min(0.45, (w * 0.55) / (g.dist(near, head) || 1));
    const width = (t) => {
      if (t < 1 - cap) return w * (0.75 + t * 0.35);
      const u = (t - 1 + cap) / cap;
      return w * 1.1 * Math.sqrt(Math.max(0, 1 - u * u));
    };
    g.ribbon(pts, { width, color: SKIN, ink: MARK, alpha, hatch: o.heavy });
    // a couple of his spots ride along the tube
    for (const t of o.heavy ? [0.35, 0.6] : [0.5]) g.blob(pts[Math.round(t * 32)], w * 0.16, { color: SKIN, ink: MARK, alpha, seed: 5 + t * 40 });
    // speed lines behind the head while it's still going out
    if (g.frame <= s0 + 1) for (const k of [-1, 1]) {
      const p0 = [head[0] - d[0] * len * 0.7 + nrm[0] * k * w * 0.8, head[1] - d[1] * len * 0.7 + nrm[1] * k * w * 0.8];
      g.line([p0, g.lerp(p0, [head[0] + nrm[0] * k * w * 0.8, head[1] + nrm[1] * k * w * 0.8], 0.6)], { color: MARK, width: 1.6, alpha: 0.8 });
    }
    // the slap: a smack of green dashes off the tip and a few drops of slime
    const at = tip, deg = g.angle(near, far);
    g.flecks(at, { t: g.span(s0, s0 + 9), n: o.heavy ? 9 : 6, dist: o.heavy ? 56 : 36, len: 14, deg, spread: 150, color: MARK, seed: s0 * 13 + i });
    drops(g, at, s0, { n: o.heavy ? 6 : 3, deg: 90 + (deg - 90) * 0.5, spread: 100, dist: o.heavy ? 60 : 36, r: o.heavy ? 6 : 4 });
  };
  // a flat lens of goo lying on the floor round x (fighter space), half-width w, thickness hgt
  const goo = (g, c, w, hgt, o = {}) => {
    const pts = [];
    for (let k = 0; k <= 16; k++) pts.push([c[0] + (k / 8 - 1) * w, c[1]]);
    g.ribbon(pts, { width: (t) => hgt * Math.sqrt(Math.max(0, 1 - (2 * t - 1) * (2 * t - 1))) * (0.8 + 0.2 * g.noise(Math.round(t * 16) * 7 + (o.seed ?? 0))), ...GOO, ...o });
  };

  const draws = {
    jab1: (g) => snout(g, 0, { w: 16, lead: 2, lag: 5 }),
    ftilt: (g) => snout(g, 0),
    dashAttack: (g) => {
      g.smear({ count: 3, alpha: 0.4 });
      g.under(() => goo(g, g.at(-30, -2), 70 * (1 - g.span(24, 38)), 8, { alpha: 0.7 * (1 - g.span(24, 38)), seed: 3 }));
      snout(g, 0, { w: 20 });
    },
    nair: (g) => snout(g, 0, { bow: -1.4 }),
    fair: (g) => snout(g, 0, { w: 24 }),
    bair: (g) => { if (g.hit(0).live) g.smear({ count: 2 }); snout(g, 0, { w: 24, bow: -1 }); },
    utilt: (g) => snout(g, 0, { bow: 1.4 }),
    uair: (g) => snout(g, 0, { bow: -1.4 }),
    dtilt: (g) => { snout(g, 0, { w: 18, bow: 0.4 }); g.dust(40, 100, 7, { n: 3 }); },
    // BELLY FLOP: he goes flat and slime sprays out from under him, spike lines straight down
    dair: (g) => {
      const h = g.hit(0), [s0, e] = h.frames;
      if (g.frame >= s0 - 3 && g.frame <= e) g.smear({ count: 3, alpha: 0.4 });
      const t = g.span(s0 - 2, e + 8);
      if (t > 0 && t < 1) {
        goo(g, g.at(0, -2), 50 + 40 * g.ease(t), 22 * (1 - t), { alpha: 1 - t * t, seed: s0 });
        for (const k of [-36, -12, 12, 36]) {
          const top = g.at(k, 4), len = 46 * g.ease(g.span(s0 - 2, s0)) * (1 - g.span(e, e + 6));
          if (len > 1) g.ribbon([top, [top[0], top[1] + len * 0.5], [top[0], top[1] + len]], { width: (u) => 10 * (1 - u), ...GOO });
        }
      }
      drops(g, g.at(-40, -8), s0, { n: 4, deg: 145, spread: 50, dist: 60 });
      drops(g, g.at(40, -8), s0, { n: 4, deg: 35, spread: 50, dist: 60 });
    },
    // the charged slap: the longest, fattest snout, the tip bursting into a splat of slime
    fsmash: (g) => {
      if (g.frame >= 13 && g.frame <= 21) g.smear({ count: 3, alpha: 0.45 });
      const tip = g.hit(0), s0 = tip.frames[0];
      snout(g, 1, { tipOf: 0, w: 30, heavy: true, lag: 10, lead: 4 });
      g.burst([tip.x2, tip.y2], tip.r * 1.4, g.span(s0, s0 + 12), { ...GOO, width: 14, n: 10 });
      g.dust(-20, 40, s0, { n: 3 });
    },
    usmash: (g) => {
      if (g.frame >= 12 && g.frame <= 20) g.smear({ count: 3, alpha: 0.4 });
      const h = g.hit(0);
      snout(g, 0, { w: 30, heavy: true, lag: 10, lead: 4, bow: 0.6 });
      g.burst([h.x2, h.y2], h.r * 1.3, g.span(h.frames[0], h.frames[0] + 12), { ...GOO, width: 12, n: 10 });
      g.dust(-40, 40, h.frames[0], { n: 3 });
    },
    // a low slap forward along the floor, then one back
    dsmash: (g) => {
      for (const i of [0, 1]) {
        const h = g.hit(i);
        snout(g, i, { w: 26, heavy: true, bow: 0.3, lag: 8 });
        g.under(() => { const t = g.span(h.frames[0], h.frames[0] + 20); if (t > 0 && t < 1) goo(g, [h.x2, g.at(0, -2)[1]], 30 + 20 * t, 10 * (1 - t), { alpha: 1 - t, seed: i }); });
        g.dust(i ? -40 : 40, i ? -110 : 110, h.frames[0], { n: 3 });
      }
    },
    // SPIT: a spray from the mouth as the glob leaves (the glob draws itself)
    nspecial: (g) => {
      const mouth = g.pose(330, 290);
      g.flecks(mouth, { t: g.span(14, 23), n: 6, dist: 40, len: 12, deg: 30, spread: 60, color: GOO.ink, seed: 21 });
      drops(g, mouth, 14, { n: 3, deg: 20, spread: 50, dist: 34, r: 4 });
    },
    // GOO SLIDE: belly first on a sheet of slime, a wave of goo curling up in front of him
    sspecial: (g) => {
      const h = g.hit(0), [s0, e] = h.frames, fade = g.span(e, e + 10);
      if (g.frame < s0 - 3 || fade >= 1) return;
      const come = g.ease(g.span(s0 - 3, s0)), a = 1 - fade;
      g.smear({ count: 4, alpha: 0.4 * a });
      g.under(() => goo(g, g.at(-60, -2), 110 * come, 10, { alpha: 0.8 * a, seed: 4 }));
      // the bow wave: from under his front, round the hitbox's leading edge, curling back over the top
      const c = g.at(48, -34), r = h.r * 1.15 * come;
      const wave = g.arc(c, r, 260, 260 + 180 * come, 18).map((p, k) => [p[0], p[1] + (g.noise(k * 11 + Math.floor(g.frame / 3)) - 0.5) * 6]);
      g.ribbon(wave, { width: (t) => 18 * a * (0.3 + t) * (t > 0.85 ? (1 - t) / 0.15 : 1), ...GOO, core: "#ffffff", alpha: a });
      drops(g, g.toward(c, 70, r), s0 + 4, { n: 3, deg: 120, spread: 50, dist: 40, r: 4 });
      drops(g, g.toward(c, 70, r), s0 + 10, { n: 3, deg: 130, spread: 40, dist: 40, r: 4 });
    },
    // STICKY PUDDLE: goo oozes off his front and drips to the floor where the puddle lands (the puddle draws itself)
    dspecial: (g) => {
      const t = g.span(6, 12);
      if (t > 0 && t < 1) for (const [x, k] of [[14, 0], [26, 1]]) {
        const p = g.at(x, -26 + 20 * t * t);
        g.ribbon([g.at(x, -28), p], { width: (u) => 3 + 5 * u, ...GOO });
        g.blob(p, 4 + k, { ...GOO, seed: k });
      }
    },
    // GOO GEYSER: a jet of slime from under him to the ground he left, splashing out where it hits
    uspecial: (g) => {
      const h = g.hit(0), [s0, e] = h.frames, fade = g.span(30, 38);
      if (g.frame < s0 - 2 || fade >= 1) return;
      // the jet reaches back down to where he took off: how far the geyser hook has lifted him by now
      const n = Math.max(0, Math.min(g.frame, 32) - 3), rise = 8.1 * n - 0.1 * n * (n - 1);
      const strong = 1 - g.span(e, e + 10) * 0.6, len = 20 + rise;
      const top = g.at(0, -8), pts = [];
      for (let k = 0; k <= 12; k++) { const t = k / 12, p = g.at(0, -20 + len * t); pts.push([p[0] + (g.noise(k * 9 + Math.floor(g.frame / 2) * 5) - 0.5) * 24 * t * (1 - t), p[1]]); }
      g.under(() => g.ribbon(pts, { width: (t) => (26 + 40 * t) * strong * (1 - fade), ...GOO, core: "#ffffff", alpha: 1 - fade }));
      g.burst([h.x1, h.y1], h.r, g.span(s0, s0 + 12), { ...GOO, width: 16, n: 10 });
      drops(g, top, s0, { n: 5, deg: 90, spread: 160, dist: 50 });
      drops(g, top, s0 + 9, { n: 4, deg: 90, spread: 150, dist: 40, r: 4 });
      if (g.frame <= e + 4) g.smear({ count: 3, alpha: 0.35 });
    },
    ledgeAttack: (g) => snout(g, 0),
    getupAttack: (g) => { snout(g, 0, { w: 18, bow: 0.3 }); snout(g, 1, { w: 18, bow: 0.3 }); },
    // the spat glob (frame is its age, at() measures from it): a lumpy ball of goo with a drippy tail behind it
    glob: (g) => {
      const c = g.at(0, 0), r = g.hit(0).r, sp = g.dist([0, 0], [g.vx, g.vy]) || 1;
      const tail = [c[0] - g.vx / sp * r * 2.4, c[1] - g.vy / sp * r * 2.4];
      g.ribbon([tail, g.lerp(tail, c, 0.5), c], { width: (t) => r * 1.5 * t, ...GOO, alpha: 0.7 });
      g.blob(c, r * 1.1, { ...GOO, lumpy: 0.18 });
      g.blob([c[0] - r * 0.35, c[1] - r * 0.35], r * 0.28, { color: "#ffffff", ink: "#ffffff", alpha: 0.9 });
    },
    // the sticky puddle: spreads out flat as it lands, bubbles, thins away at the end
    puddle: (g) => {
      const c = g.at(0, 4), r = g.hit(0).r, left = g.total - g.frame;
      const a = Math.min(1, left / 30), spread = 0.5 + 0.5 * g.ease(g.span(0, 8));
      goo(g, c, r * 1.4 * spread, 14 * spread, { alpha: 0.9 * a, seed: 7 });
      for (let k = 0; k < 3; k++) {
        const phase = (g.frame + k * 17) % 50, t = phase / 50;
        if (t < 0.8) g.blob([c[0] + (k - 1) * r * 0.7, c[1] - 3 - t * 4], 2 + t * 4, { color: "#d6f3da", ink: GOO.ink, alpha: a * (1 - t), seed: k });
      }
    },
    // a patch of his trail: a thin glossy streak on the floor that dries away
    slime: (g) => {
      const c = g.at(0, 1), w = g.hit(0).r, a = Math.min(1, (g.total - g.frame) / 40) * 0.55;
      goo(g, c, w * 1.2, 6, { color: "#bfe9a8", ink: "#5fc94a", alpha: a, seed: 1 });
    },
  };
  // a draw named after a move draws that move; the rest (glob, puddle, slime) are projectile kinds
  for (const id of Object.keys(draws)) if (moves[id]) moves[id].draw = id;

  return {
    id: "slugbert",
    name: "SLUGBERT",
    tagline: "Slow, soggy, and absolutely everywhere.",
    stats,
    moves,
    rig: { anims: spriteAnims(), loops: spriteLoops },
    palette: { colors: { marker: "#4f9e63" }, outline: "#2c3a2e" },
    looks,
    draws,
    special: () => {
      const s = { next: 0 };
      for (let i = 0; i < N; i++) { s["x" + i] = 0; s["y" + i] = 0; s["w" + i] = 0; s["t" + i] = 0; }
      return s;
    },
    hooks: {
      spit: ({ state, f }) => {
        if (f.frame === 14 && spend(f, 25)) {
          spawnProjectile(state, f, "glob", f.x + f.moveFacing * 60, f.y - 62, f.moveFacing * 7.5, -5, 90,
            { frames: [0, 999], x: 0, y: 0, r: 18, damage: 10, angle: 55, base: 38, growth: 55 }, { g: 0.3, bounce: 1 });
        }
      },
      slide: ({ state, f }) => {
        if (f.frame === 8) {
          if (f.grounded && spend(f, 30)) layPuddle(state, f, f.x, 200, 5);
          f.vx = f.moveFacing * 9;
        }
        if (f.frame > 8 && f.frame <= 22) f.vx = f.moveFacing * (9 - (f.frame - 8) * 0.45);
      },
      puddle: ({ state, f }) => {
        if (f.frame === 12 && f.grounded && spend(f, 40)) layPuddle(state, f, f.x + f.moveFacing * 20, 360, 9);
      },
      geyser: ({ f, input }) => {
        if (f.frame === 4) { f.grounded = false; f.platform = -1; f.usedUpSpecial = true; }
        if (f.frame >= 4 && f.frame <= 32) {
          f.vy = -8.5 + (f.frame - 4) * 0.2;
          f.vx = (input.x / 100) * 3.8;
        }
      },
    },
    onFrame: ({ state, f }) => {
      const s = f.special;
      for (let i = 0; i < N; i++) if (s["t" + i] > 0) s["t" + i]--;
      f.bars.slime += 0.3;
      if (f.grounded) {
        const slick = onSlime(s, f.x, f.y);
        const speed = Math.abs(f.vx);
        // crawling on its own slime: double speed
        if (slick && speed > 0.5 && speed <= stats.run + 0.5) f.x += f.vx;
        // fresh ground: leave a patch behind (3 slime each)
        if (!slick && speed > 1 && f.bars.slime >= 3) { f.bars.slime -= 3; stamp(state, f, f.x, f.y, 14, 180); }
      }
      for (const g of state.fighters) {
        if (g === f || !g.grounded || Math.abs(g.vx) <= 1 || !onSlime(s, g.x, g.y)) continue;
        // everyone else slips: their slide keeps going
        g.vx = Math.max(-6, Math.min(6, g.vx + (g.vx > 0 ? 0.25 : -0.25)));
      }
    },
    bars: { slime: { label: "SLIME", color: "#6cc07e", max: SLIME_MAX, start: SLIME_MAX } },
  };
}
